# -*- coding: utf-8 -*-
# 8-din-kulturu-ve-ahlak-bilgisi-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAUN SURESİNİN GENEL ÖZELLİKLERİ VE KİMLİĞİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Surenin Temel Bilgileri</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" fill="#1e3a8a">• İniş Dönemi: Mekke Dönemi (Mekkî)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="12" fill="#1e3a8a">• Ayet Sayısı: 7 Ayet</text>\n  <text x="180" y="144" text-anchor="middle" font-size="12" fill="#1e3a8a">• Mushaftaki Sırası: 107. Sure (30. Cüz)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="12" fill="#1e3a8a">• Konusu: Hesap günü bilinci, yetim ve</text>\n  <text x="180" y="186" text-anchor="middle" font-size="12" fill="#1e3a8a">yoksulu gözetme, ibadette ihlas ve</text>\n  <text x="180" y="204" text-anchor="middle" font-size="12" fill="#1e3a8a">komşulukta yardımlaşma ahlakı.</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">«Maun» (الْمَاعُونَ) Kelimesinin Anlamı</text>\n  <text x="520" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">7. Ayetteki «وَيَمْنَعُونَ الْمَاعُونَ» İfadesi</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11" fill="#14532d">Surenin adı son ayette geçen «el-Mâûn»</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11" fill="#14532d">kelimesinden alınmıştır:</text>\n  <line x1="385" y1="152" x2="655" y2="152" stroke="#86efac" stroke-width="1"/>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1. Yardım, iyilik, zekât ve sadaka</text>\n  <text x="520" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Komşular arasında ödünç alınıp verilen</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" fill="#14532d">günlük ev eşyası (kap kacak, tuz, su, balta vb.)</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAUN SURESİNİN GENEL ÖZELLİKLERİ VE KİMLİĞİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Surenin Temel Bilgileri</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" fill="#1e3a8a">• İniş Dönemi: Mekke Dönemi (Mekkî)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="12" fill="#1e3a8a">• Ayet Sayısı: 7 Ayet</text>\n  <text x="180" y="144" text-anchor="middle" font-size="12" fill="#1e3a8a">• Mushaftaki Sırası: 107. Sure (30. Cüz)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="12" fill="#1e3a8a">• Konusu: Hesap günü bilinci, yetim ve</text>\n  <text x="180" y="186" text-anchor="middle" font-size="12" fill="#1e3a8a">yoksulu gözetme, ibadette ihlas ve</text>\n  <text x="180" y="204" text-anchor="middle" font-size="12" fill="#1e3a8a">komşulukta yardımlaşma ahlakı.</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">«Maun» (الْمَاعُونَ) Kelimesinin Anlamı</text>\n  <text x="520" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">7. Ayetteki «وَيَمْنَعُونَ الْمَاعُونَ» İfadesi</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11" fill="#14532d">Surenin adı son ayette geçen «el-Mâûn»</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11" fill="#14532d">kelimesinden alınmıştır:</text>\n  <line x1="385" y1="152" x2="655" y2="152" stroke="#86efac" stroke-width="1"/>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">1. Yardım, iyilik, zekât ve sadaka</text>\n  <text x="520" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Komşular arasında ödünç alınıp verilen</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" fill="#14532d">günlük ev eşyası (kap kacak, tuz, su, balta vb.)</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAUN SURESİNİN OKUNUŞU VE TÜRKÇE ANLAMI (MEALİ)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Surenin Okunuşu</text>\n  <text x="180" y="88" text-anchor="middle" font-size="10.5" fill="#78350f">Bismillâhirrahmânirrahîm</text>\n  <text x="180" y="108" text-anchor="middle" font-size="10.5" fill="#92400e">1. Era\'eytellezî yükezzibu bi\'d-dîn.</text>\n  <text x="180" y="126" text-anchor="middle" font-size="10.5" fill="#92400e">2. Fezâlikellezî yedu\'\'ul-yetîm.</text>\n  <text x="180" y="144" text-anchor="middle" font-size="10.5" fill="#92400e">3. Ve lâ yehuddu alâ ta\'âmi\'l-miskîn.</text>\n  <text x="180" y="162" text-anchor="middle" font-size="10.5" fill="#92400e">4. Feveylün li\'l-musallîn.</text>\n  <text x="180" y="180" text-anchor="middle" font-size="10.5" fill="#92400e">5. Ellezîne hüm an salâtihim sâhûn.</text>\n  <text x="180" y="198" text-anchor="middle" font-size="10.5" fill="#92400e">6. Ellezîne hüm yürâûn.</text>\n  <text x="180" y="216" text-anchor="middle" font-size="10.5" fill="#92400e">7. Ve yemne\'ûne\'l-mâ\'ûn.</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="520" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Surenin Türkçe Anlamı</text>\n  <text x="520" y="88" text-anchor="middle" font-size="10" fill="#0c4a6e">Rahmân ve Rahîm olan Allah\'ın adıyla</text>\n  <text x="520" y="108" text-anchor="middle" font-size="10" fill="#075985">1. Dini (hesap gününü) yalanlayanı gördün mü?</text>\n  <text x="520" y="126" text-anchor="middle" font-size="10" fill="#075985">2. İşte o, yetimi itip kakar.</text>\n  <text x="520" y="144" text-anchor="middle" font-size="10" fill="#075985">3. Yoksulu doyurmaya teşvik etmez (önayak olmaz).</text>\n  <text x="520" y="162" text-anchor="middle" font-size="10" fill="#075985">4. Yazıklar olsun o namaz kılanlara ki,</text>\n  <text x="520" y="180" text-anchor="middle" font-size="10" fill="#075985">5. Onlar namazlarını ciddiye almazlar (gaflettedirler).</text>\n  <text x="520" y="198" text-anchor="middle" font-size="10" fill="#075985">6. Onlar (ibadetleriyle) gösteriş yaparlar.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="10" fill="#075985">7. Ufacık bir yardıma (ödünce) bile engel olurlar.</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAUN SURESİNİN OKUNUŞU VE TÜRKÇE ANLAMI (MEALİ)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Surenin Okunuşu</text>\n  <text x="180" y="88" text-anchor="middle" font-size="10.5" fill="#78350f">Bismillâhirrahmânirrahîm</text>\n  <text x="180" y="108" text-anchor="middle" font-size="10.5" fill="#92400e">1. Era\'eytellezî yükezzibu bi\'d-dîn.</text>\n  <text x="180" y="126" text-anchor="middle" font-size="10.5" fill="#92400e">2. Fezâlikellezî yedu\'\'ul-yetîm.</text>\n  <text x="180" y="144" text-anchor="middle" font-size="10.5" fill="#92400e">3. Ve lâ yehuddu alâ ta\'âmi\'l-miskîn.</text>\n  <text x="180" y="162" text-anchor="middle" font-size="10.5" fill="#92400e">4. Feveylün li\'l-musallîn.</text>\n  <text x="180" y="180" text-anchor="middle" font-size="10.5" fill="#92400e">5. Ellezîne hüm an salâtihim sâhûn.</text>\n  <text x="180" y="198" text-anchor="middle" font-size="10.5" fill="#92400e">6. Ellezîne hüm yürâûn.</text>\n  <text x="180" y="216" text-anchor="middle" font-size="10.5" fill="#92400e">7. Ve yemne\'ûne\'l-mâ\'ûn.</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="520" y="66" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Surenin Türkçe Anlamı</text>\n  <text x="520" y="88" text-anchor="middle" font-size="10" fill="#0c4a6e">Rahmân ve Rahîm olan Allah\'ın adıyla</text>\n  <text x="520" y="108" text-anchor="middle" font-size="10" fill="#075985">1. Dini (hesap gününü) yalanlayanı gördün mü?</text>\n  <text x="520" y="126" text-anchor="middle" font-size="10" fill="#075985">2. İşte o, yetimi itip kakar.</text>\n  <text x="520" y="144" text-anchor="middle" font-size="10" fill="#075985">3. Yoksulu doyurmaya teşvik etmez (önayak olmaz).</text>\n  <text x="520" y="162" text-anchor="middle" font-size="10" fill="#075985">4. Yazıklar olsun o namaz kılanlara ki,</text>\n  <text x="520" y="180" text-anchor="middle" font-size="10" fill="#075985">5. Onlar namazlarını ciddiye almazlar (gaflettedirler).</text>\n  <text x="520" y="198" text-anchor="middle" font-size="10" fill="#075985">6. Onlar (ibadetleriyle) gösteriş yaparlar.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="10" fill="#075985">7. Ufacık bir yardıma (ödünce) bile engel olurlar.</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1-3. AYETLER: HESAP GÜNÜNÜ YALANLAYANLARIN ÖZELLİKLERİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">1. Ayet: Hesap Gününü İnkâr</text>\n  <text x="125" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">يُكَذِّبُ بِالدِّينِ</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11" fill="#7f1d1d">Buradaki «ed-Dîn» kavramı</text>\n  <text x="125" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">ahiret, ceza ve hesap günü</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" fill="#7f1d1d">anlamındadır. Hesap vereceğine</text>\n  <text x="125" y="176" text-anchor="middle" font-size="11" fill="#7f1d1d">inanmayan kişi merhametten</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11" fill="#7f1d1d">ve adaletten uzaklaşır.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#c2410c">2. Ayet: Yetimi İtip Kakmak</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">يَدُعُّ الْيَتِيمَ</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" fill="#7c2d12">Yetimi hor görmek, hakkını</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11" fill="#7c2d12">yemek ve ona kaba davranmaktır.</text>\n  <text x="350" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Müminin Tutumu:</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11" fill="#14532d">Yetimin başını okşamak,</text>\n  <text x="350" y="204" text-anchor="middle" font-size="11" fill="#14532d">korumak ve hakkını gözetmektir.</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fae8ff" stroke="#c026d3" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#a21caf">3. Ayet: Yoksulu Gözetmemek</text>\n  <text x="575" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#86198f">وَلَا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11" fill="#701a75">Kendisi yoksula yardım etmediği</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" fill="#701a75">gibi başkalarını da yoksulu</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#701a75">doyurmaya teşvik etmez.</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">İslam ise hayra öncülük</text>\n  <text x="575" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">etmeyi emreder.</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1-3. AYETLER: HESAP GÜNÜNÜ YALANLAYANLARIN ÖZELLİKLERİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">1. Ayet: Hesap Gününü İnkâr</text>\n  <text x="125" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">يُكَذِّبُ بِالدِّينِ</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11" fill="#7f1d1d">Buradaki «ed-Dîn» kavramı</text>\n  <text x="125" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">ahiret, ceza ve hesap günü</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" fill="#7f1d1d">anlamındadır. Hesap vereceğine</text>\n  <text x="125" y="176" text-anchor="middle" font-size="11" fill="#7f1d1d">inanmayan kişi merhametten</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11" fill="#7f1d1d">ve adaletten uzaklaşır.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#c2410c">2. Ayet: Yetimi İtip Kakmak</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">يَدُعُّ الْيَتِيمَ</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11" fill="#7c2d12">Yetimi hor görmek, hakkını</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11" fill="#7c2d12">yemek ve ona kaba davranmaktır.</text>\n  <text x="350" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Müminin Tutumu:</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11" fill="#14532d">Yetimin başını okşamak,</text>\n  <text x="350" y="204" text-anchor="middle" font-size="11" fill="#14532d">korumak ve hakkını gözetmektir.</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fae8ff" stroke="#c026d3" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#a21caf">3. Ayet: Yoksulu Gözetmemek</text>\n  <text x="575" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#86198f">وَلَا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11" fill="#701a75">Kendisi yoksula yardım etmediği</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" fill="#701a75">gibi başkalarını da yoksulu</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#701a75">doyurmaya teşvik etmez.</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">İslam ise hayra öncülük</text>\n  <text x="575" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#86198f">etmeyi emreder.</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">4-7. AYETLER: İBADETTE SAMİMİYET (İHLAS) VE YARDIMLAŞMA</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Surede Kınanan Olumsuz Tutumlar</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• سَاهُونَ (Gaflet / Ciddiyetsizlik):</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#7f1d1d">Namazın ruhundan, bilincinden ve</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" fill="#7f1d1d">kazandırdığı ahlaktan habersiz olmak.</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• يُرَاءُونَ (Riya / Gösteriş):</text>\n  <text x="180" y="174" text-anchor="middle" font-size="11" fill="#7f1d1d">İbadetleri ve iyilikleri Allah rızası için değil,</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" fill="#7f1d1d">insanlar görsün ve övsün diye yapmak.</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• يَمْنَعُونَ الْمَاعُونَ (Yardımı Esirgemek)</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Müminin Olması Gereken Tutumu</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• Huşû ve Bilinç:</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#14532d">Namazı vaktinde, anlamına uygun ve</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" fill="#14532d">kötülüklerden alıkoyacak bilinçle kılmak.</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• İhlas (Samimiyet):</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#14532d">Her ibadeti ve sadakayı gösterişten uzak,</text>\n  <text x="520" y="190" text-anchor="middle" font-size="11" fill="#14532d">sırf Yüce Allah\'ın rızasını kazanmak için yapmak.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• Cömertlik ve Paylaşma Ahlakı</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">4-7. AYETLER: İBADETTE SAMİMİYET (İHLAS) VE YARDIMLAŞMA</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Surede Kınanan Olumsuz Tutumlar</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• سَاهُونَ (Gaflet / Ciddiyetsizlik):</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#7f1d1d">Namazın ruhundan, bilincinden ve</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" fill="#7f1d1d">kazandırdığı ahlaktan habersiz olmak.</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• يُرَاءُونَ (Riya / Gösteriş):</text>\n  <text x="180" y="174" text-anchor="middle" font-size="11" fill="#7f1d1d">İbadetleri ve iyilikleri Allah rızası için değil,</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" fill="#7f1d1d">insanlar görsün ve övsün diye yapmak.</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">• يَمْنَعُونَ الْمَاعُونَ (Yardımı Esirgemek)</text>\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Müminin Olması Gereken Tutumu</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• Huşû ve Bilinç:</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#14532d">Namazı vaktinde, anlamına uygun ve</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" fill="#14532d">kötülüklerden alıkoyacak bilinçle kılmak.</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• İhlas (Samimiyet):</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#14532d">Her ibadeti ve sadakayı gösterişten uzak,</text>\n  <text x="520" y="190" text-anchor="middle" font-size="11" fill="#14532d">sırf Yüce Allah\'ın rızasını kazanmak için yapmak.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">• Cömertlik ve Paylaşma Ahlakı</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAUN SURESİNDE İMAN — İBADET — AHLAK BÜTÜNLÜĞÜ</text>\n  <rect x="30" y="60" width="190" height="160" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="125" y="90" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. İMAN BOYUTU</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" fill="#1e3a8a">Ahiret ve hesap gününe</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11" fill="#1e3a8a">(يَوْمُ الدِّينِ)</text>\n  <text x="125" y="154" text-anchor="middle" font-size="11" fill="#1e3a8a">içtenlikle inanmak ve</text>\n  <text x="125" y="172" text-anchor="middle" font-size="11" fill="#1e3a8a">sorumluluk bilinci taşımak.</text>\n  <line x1="220" y1="140" x2="255" y2="140" stroke="#64748b" stroke-width="2"/>\n  <polygon points="255,140 247,135 247,145" fill="#64748b"/>\n  <rect x="255" y="60" width="190" height="160" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="2"/>\n  <text x="350" y="90" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. İBADET BOYUTU</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#14532d">Namazı gafletten ve</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#14532d">gösterişten (riyadan) uzak,</text>\n  <text x="350" y="154" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">ihlas ve huşû ile</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11" fill="#14532d">yerine getirmek.</text>\n  <line x1="445" y1="140" x2="480" y2="140" stroke="#64748b" stroke-width="2"/>\n  <polygon points="480,140 472,135 472,145" fill="#64748b"/>\n  <rect x="480" y="60" width="190" height="160" rx="10" fill="#fef3c7" stroke="#f59e0b" stroke-width="2"/>\n  <text x="575" y="90" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">3. AHLAK BOYUTU</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" fill="#78350f">Yetimi korumak, yoksulu</text>\n  <text x="575" y="136" text-anchor="middle" font-size="11" fill="#78350f">doyurmak, zekât/sadaka</text>\n  <text x="575" y="154" text-anchor="middle" font-size="11" fill="#78350f">vermek ve en küçük yardımı</text>\n  <text x="575" y="172" text-anchor="middle" font-size="11" fill="#78350f">dahi esirgememek.</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAUN SURESİNDE İMAN — İBADET — AHLAK BÜTÜNLÜĞÜ</text>\n  <rect x="30" y="60" width="190" height="160" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="125" y="90" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. İMAN BOYUTU</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" fill="#1e3a8a">Ahiret ve hesap gününe</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11" fill="#1e3a8a">(يَوْمُ الدِّينِ)</text>\n  <text x="125" y="154" text-anchor="middle" font-size="11" fill="#1e3a8a">içtenlikle inanmak ve</text>\n  <text x="125" y="172" text-anchor="middle" font-size="11" fill="#1e3a8a">sorumluluk bilinci taşımak.</text>\n  <line x1="220" y1="140" x2="255" y2="140" stroke="#64748b" stroke-width="2"/>\n  <polygon points="255,140 247,135 247,145" fill="#64748b"/>\n  <rect x="255" y="60" width="190" height="160" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="2"/>\n  <text x="350" y="90" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. İBADET BOYUTU</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11" fill="#14532d">Namazı gafletten ve</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#14532d">gösterişten (riyadan) uzak,</text>\n  <text x="350" y="154" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">ihlas ve huşû ile</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11" fill="#14532d">yerine getirmek.</text>\n  <line x1="445" y1="140" x2="480" y2="140" stroke="#64748b" stroke-width="2"/>\n  <polygon points="480,140 472,135 472,145" fill="#64748b"/>\n  <rect x="480" y="60" width="190" height="160" rx="10" fill="#fef3c7" stroke="#f59e0b" stroke-width="2"/>\n  <text x="575" y="90" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">3. AHLAK BOYUTU</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" fill="#78350f">Yetimi korumak, yoksulu</text>\n  <text x="575" y="136" text-anchor="middle" font-size="11" fill="#78350f">doyurmak, zekât/sadaka</text>\n  <text x="575" y="154" text-anchor="middle" font-size="11" fill="#78350f">vermek ve en küçük yardımı</text>\n  <text x="575" y="172" text-anchor="middle" font-size="11" fill="#78350f">dahi esirgememek.</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAUN SURESİNİN ZEKÂT VE SADAKA ÜNİTESİYLE İLİŞKİSİ</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Bireysel Arınma ve Samimiyet</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#075985">• Zekât ve sadaka verirken başa kakmak</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11.5" fill="#075985">veya gösteriş (riya) yapmak ibadetin</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11.5" fill="#075985">sevabını ortadan kaldırır (Bakara 264).</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11.5" fill="#075985">• Maun suresi de insanı bencillik ve</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11.5" fill="#075985">gösterişten arındırarak gerçek ihlas</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11.5" fill="#075985">bilincine ulaştırır.</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fae8ff" stroke="#c026d3" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a21caf">Toplumsal Dayanışma ve Merhamet</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#86198f">• Yetimlerin ve yoksulların gözetilmesi</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11.5" fill="#86198f">toplumda sevgi ve güveni artırır.</text>\n  <text x="520" y="146" text-anchor="middle" font-size="11.5" fill="#86198f">• Komşular arasında küçük ev eşyalarının</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11.5" fill="#86198f">(mâûn) ödünç verilmesi bile İslam\'da</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11.5" fill="#86198f">ibadet bilincinin ayrılmaz bir</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11.5" fill="#86198f">parçası kabul edilmiştir.</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAUN SURESİNİN ZEKÂT VE SADAKA ÜNİTESİYLE İLİŞKİSİ</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Bireysel Arınma ve Samimiyet</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#075985">• Zekât ve sadaka verirken başa kakmak</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11.5" fill="#075985">veya gösteriş (riya) yapmak ibadetin</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11.5" fill="#075985">sevabını ortadan kaldırır (Bakara 264).</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11.5" fill="#075985">• Maun suresi de insanı bencillik ve</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11.5" fill="#075985">gösterişten arındırarak gerçek ihlas</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11.5" fill="#075985">bilincine ulaştırır.</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fae8ff" stroke="#c026d3" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a21caf">Toplumsal Dayanışma ve Merhamet</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#86198f">• Yetimlerin ve yoksulların gözetilmesi</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11.5" fill="#86198f">toplumda sevgi ve güveni artırır.</text>\n  <text x="520" y="146" text-anchor="middle" font-size="11.5" fill="#86198f">• Komşular arasında küçük ev eşyalarının</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11.5" fill="#86198f">(mâûn) ödünç verilmesi bile İslam\'da</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11.5" fill="#86198f">ibadet bilincinin ayrılmaz bir</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11.5" fill="#86198f">parçası kabul edilmiştir.</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
